#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Bootstraps doco-cd and the ops Platform Stack on nc8kg1101, once, after asotbz/ops#300 merged.
# Runbook: README.md#bootstrapping-doco-cd. Run it from a checkout of asotbz/ops on @jbruns' machine:
#   scripts/bootstrap-nc8kg1101.sh
# Re-running is safe: each stage checks what is already done. Settings (environment overrides):
#   OPERATOR      sudo-capable login on the Host (default doogie@nc8kg1101.asot.bz)
#   AGE_KEY_FILE  the Host's private age key on this machine (default ~/.config/sops/age/nc8kg1101.txt)

TOTAL_STAGES=10

OPERATOR="${OPERATOR:-doogie@nc8kg1101.asot.bz}"
AGE_KEY_FILE="${AGE_KEY_FILE:-$HOME/.config/sops/age/nc8kg1101.txt}"
HOST_AGE_KEY="/etc/doco-cd/age.key"
REPO_URL="https://github.com/asotbz/ops.git"
URLS_FILE="nc8kg1101/ops/doco-cd/apprise_urls.sops.txt"
URLS_PLACEHOLDER="PLACEHOLDER-set-by-bootstrap-wizard"
STACK_BACK_ENV="nc8kg1101/ops/stack-back.sops.env"
LEGACY_PROJECTS="asot common monitoring xfer"
OLD_APPRISE_VOLUME="xfer_apprise_config"
NEW_APPRISE_VOLUME="ops_apprise_config"
STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/ops-bootstrap-nc8kg1101"

die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# agent CMD runs CMD on the Host as the ops agent (sudo -n docker only, no password, no tty); reads.
agent() { ssh -i "$SSH_KEY" -o BatchMode=yes "$HOPS_NC8KG1101_SSH_USER@$HOPS_NC8KG1101_SSH_HOST" "$@"; }
# operator CMD runs CMD on the Host as the operator, with a tty for sudo's password prompt; changes.
operator() { ssh -t "$OPERATOR" "$@"; }
# exists KIND NAME succeeds when the Host has that volume, network or container.
exists() { agent "sudo -n docker $1 inspect $2 >/dev/null 2>&1"; }

# image SERVICE prints the image a Service pins in nc8kg1101/ops, so the wizard follows Renovate's bumps.
image() { sed -n 's/^ *image: *//p' "nc8kg1101/ops/$1/service.yaml" | head -n1; }

# legacy_snapshot prints every legacy container with its id and start time, to show nothing restarted it.
legacy_snapshot() {
  # shellcheck disable=SC2016 # expanded on the Host
  agent 'for p in '"$LEGACY_PROJECTS"'; do
      ids=$(sudo -n docker ps -aq --filter label=com.docker.compose.project=$p)
      [ -n "$ids" ] && sudo -n docker inspect -f "$p {{.Name}} {{.Id}} {{.State.StartedAt}}" $ids
    done | sort'
}

# wait_healthy CONTAINER waits up to ~3 minutes for a container's healthcheck to pass.
wait_healthy() {
  local status=""
  for _ in $(seq 1 36); do
    status=$(agent "sudo -n docker inspect -f '{{.State.Health.Status}}' $1" 2>/dev/null || true)
    [[ "$status" == healthy ]] && { ok "$1 is healthy"; return 0; }
    sleep 5
  done
  warn "$1 is ${status:-missing}, not healthy"
  return 1
}

cd "$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)"
mkdir -p "$STATE_DIR"

banner "Bootstrap doco-cd and the ops Platform Stack on nc8kg1101"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check prerequisites"
say "Checks this machine's tools, the repo checkout and access to the Host. Changes nothing on the Host."
for tool in git gh sops ssh scp shasum; do
  command -v "$tool" >/dev/null 2>&1 || die "$tool is not installed"
done
[[ -f .env ]] || die "no repo-root .env; copy .env.example and fill it in"
set -a
# shellcheck disable=SC1091
. ./.env
set +a
[[ -n "${HOPS_NC8KG1101_SSH_HOST:-}" && -n "${HOPS_NC8KG1101_SSH_USER:-}" && -n "${HOPS_NC8KG1101_SSH_KEY:-}" ]] \
  || die ".env lacks HOPS_NC8KG1101_SSH_HOST, _USER or _KEY"
SSH_KEY="${HOPS_NC8KG1101_SSH_KEY/#\~/$HOME}"
git fetch -q origin main
[[ "$(git rev-parse --abbrev-ref HEAD)" == main ]] || die "check out main first"
[[ -z "$(git status --porcelain)" ]] || die "the checkout has uncommitted changes"
git merge -q --ff-only origin/main || die "main has diverged from origin/main"
[[ -f nc8kg1101/ops/compose.yaml && -f .doco-cd.nc8kg1101.yml ]] || die "main does not hold the ops Stack yet; merge #300 first"
ok "main is up to date and holds nc8kg1101/ops"
agent true || die "cannot reach the Host as $HOPS_NC8KG1101_SSH_USER"
ok "reached the Host as $HOPS_NC8KG1101_SSH_USER"
[[ -f "$AGE_KEY_FILE" ]] || die "no Host age key at $AGE_KEY_FILE (set AGE_KEY_FILE)"
# The Host recipient: the first key of .sops.yaml's ^nc8kg1101/ rule; the other is @jbruns' editing key.
HOST_RECIPIENT=$(sed -n '/path_regex: \^nc8kg1101\//,/path_regex/p' .sops.yaml | grep -o 'age1[0-9a-z]*' | head -n1)
[[ -n "$HOST_RECIPIENT" ]] || die "no ^nc8kg1101/ recipient in .sops.yaml"
if command -v age-keygen >/dev/null 2>&1; then
  [[ "$(age-keygen -y "$AGE_KEY_FILE")" == "$HOST_RECIPIENT" ]] || die "$AGE_KEY_FILE is not the Host key ($HOST_RECIPIENT)"
  ok "$AGE_KEY_FILE holds the Host key"
else
  warn "age-keygen not found; skipping the check that $AGE_KEY_FILE is the Host key"
fi
note "Operator login for changes: $OPERATOR (sudo will ask for its password)."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "doco-cd's notification URL"
say "doco-cd posts its deploy results through apprise to the URL in $URLS_FILE."
say "#300 left a placeholder there; replacing it is a PR, merged before the bootstrap."
# Compared by hash, never shown; a failed decrypt stops the wizard rather than reading as "set".
urls_hash=$(sops -d "$URLS_FILE" | shasum -a 256) || die "cannot decrypt $URLS_FILE with your sops key"
if [[ "$urls_hash" != "$(printf '%s' "$URLS_PLACEHOLDER" | shasum -a 256)" ]]; then
  ok "the URL is already set"
elif confirm "Replace the placeholder now (otherwise doco-cd's notifications fail until someone does)?"; then
  if confirm "Reuse stack-back's Discord webhook (DISCORD_WEBHOOK in $STACK_BACK_ENV)?"; then
    URLS=$(sops -d "$STACK_BACK_ENV" | sed -n 's/^DISCORD_WEBHOOK=//p' | sed -e "s/^['\"]//" -e "s/['\"]$//")
  else
    step "Discord → Server Settings → Integrations → Webhooks → New Webhook → Copy Webhook URL."
    note "Any Apprise URL works; separate several with commas."
    ask_secret URLS "Paste the URL:"
  fi
  [[ -n "$URLS" ]] || die "no URL given"
  BRANCH="300-apprise-urls"
  git switch -q -C "$BRANCH"
  printf '%s' "$URLS" | sops encrypt --filename-override "$URLS_FILE" --input-type binary --output-type binary /dev/stdin > "$URLS_FILE.new"
  mv "$URLS_FILE.new" "$URLS_FILE"
  unset URLS
  git commit -q -m "Set doco-cd's notification URL on nc8kg1101 (#300)" -- "$URLS_FILE"
  git push -q -u origin "$BRANCH"
  gh pr create -R asotbz/ops --head "$BRANCH" --base main \
    --title "Set doco-cd's notification URL on nc8kg1101" \
    --body "Replaces the placeholder #300 left in \`$URLS_FILE\`, from the bootstrap wizard. Refs #300."
  git switch -q main
  say "Merge that PR now; the wizard waits for it."
  until [[ "$(gh pr view "$BRANCH" -R asotbz/ops --json state -q .state)" == MERGED ]]; do sleep 15; done
  git pull -q --ff-only origin main
  git branch -q -D "$BRANCH" 2>/dev/null || true
  ok "merged; main now holds the URL"
else
  SKIPPED+=("doco-cd's notification URL: replace the placeholder in $URLS_FILE through a PR")
  warn "keeping the placeholder"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Install the Host age key"
say "doco-cd decrypts SOPS files with the Host's private age key at $HOST_AGE_KEY (root, 0600, in a 0700 dir)."
say "It goes from $AGE_KEY_FILE to the Host through $OPERATOR's home, never printed, and is checked by hash."
local_hash=$(shasum -a 256 "$AGE_KEY_FILE" | cut -c1-64)
# key_installed compares by exit code only: sha256sum -c on the Host prints nothing with --status.
key_installed() { operator "echo '$local_hash  $HOST_AGE_KEY' | sudo sha256sum -c --status 2>/dev/null"; }
if key_installed; then
  ok "$HOST_AGE_KEY already holds the Host key"
elif confirm "Copy the key to $OPERATOR and install it at $HOST_AGE_KEY?"; then
  # Create the copy 0600 first: scp keeps an existing file's mode.
  ssh "$OPERATOR" 'umask 077 && : > .doco-cd-age.key.tmp'
  scp -q "$AGE_KEY_FILE" "$OPERATOR:.doco-cd-age.key.tmp"
  # shellcheck disable=SC2016 # expanded on the Host
  operator 'sudo install -d -o root -g root -m 0700 /etc/doco-cd \
    && sudo install -o root -g root -m 0600 .doco-cd-age.key.tmp '"$HOST_AGE_KEY"'; rc=$?
    shred -u .doco-cd-age.key.tmp 2>/dev/null || rm -f .doco-cd-age.key.tmp; exit $rc'
  key_installed || die "$HOST_AGE_KEY does not match $AGE_KEY_FILE"
  ok "installed; hashes match"
else
  die "doco-cd cannot decrypt anything without the key; re-run when ready"
fi
operator "sudo stat -c '%n %U:%G %a' /etc/doco-cd $HOST_AGE_KEY"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the volume and network the ops Stack expects"
say "Both are external in nc8kg1101/ops, so Compose never creates them:"
step "volume ops_doco-cd_data: doco-cd's clones and deploy state"
step "volume ops_stack-back_cache: stack-back's restic cache"
step "network metrics: owned by the monitoring Stack (ADR 0002), created here until monitoring is cut over (#302)."
note "It carries Compose's labels for monitoring's network key, so monitoring adopts it then."
note "The backup network is the ops Stack's own; Compose creates it. common_backend exists already."
missing_volumes=()
for v in ops_doco-cd_data ops_stack-back_cache; do exists volume "$v" || missing_volumes+=("$v"); done
have_network=no
exists network metrics && have_network=yes
if [[ ${#missing_volumes[@]} == 0 && "$have_network" == yes ]]; then
  ok "all exist"
elif confirm "Create the missing ones?"; then
  for v in "${missing_volumes[@]}"; do operator "sudo docker volume create $v >/dev/null"; done
  [[ "$have_network" == yes ]] || operator "sudo docker network create --driver bridge \
    --label com.docker.compose.project=monitoring --label com.docker.compose.network=metrics metrics >/dev/null"
  ok "created"
else
  die "the bootstrap fails without them; re-run when ready"
fi
exists network common_backend || die "common_backend is missing; is common up?"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Retire xfer's apprise"
say "#300 moved apprise from the xfer Stack to ops, under the same container name. The old one must be"
say "gone before ops starts the new one. xfer's Services lose notifications until stage 8: keep going."
step "Portainer → Stacks → xfer: check it redeployed from main at or after #300 (Pull and redeploy if not,"
step "with Prune services on)."
pause "Press Enter once xfer has redeployed"
old=$(agent "sudo -n docker ps -a --filter name=^apprise\$ --format '{{.Label \"com.docker.compose.project\"}} {{.State}}'")
if [[ -z "$old" ]]; then
  ok "no apprise container left"
elif [[ "$old" == ops\ * ]]; then
  ok "apprise already belongs to ops"
else
  say "Still there: apprise ($old). Its config stays in volume $OLD_APPRISE_VOLUME."
  confirm "Stop and remove the old apprise container?" || die "the new apprise cannot start beside it"
  operator "sudo docker rm -f apprise >/dev/null"
  ok "removed"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Copy apprise's saved config into the ops Stack's volume"
say "apprise keeps the asotdiscord config xfer's Services post to in $OLD_APPRISE_VOLUME."
say "It is copied into $NEW_APPRISE_VOLUME (ADR 0009); $OLD_APPRISE_VOLUME stays untouched as the Rollback"
say "Volume, released once the cutover is verified."
count() { agent "sudo -n docker run --rm --pull never --network none -v $1:/v:ro --entrypoint sh $2 -c 'find /v | wc -l'"; }
OLD_APPRISE_IMAGE="caronc/apprise:v1.5.4"
if exists volume "$NEW_APPRISE_VOLUME" && [[ "$(count "$NEW_APPRISE_VOLUME" "$OLD_APPRISE_IMAGE")" -gt 1 ]]; then
  ok "$NEW_APPRISE_VOLUME already holds a config"
elif confirm "Create $NEW_APPRISE_VOLUME and copy $OLD_APPRISE_VOLUME into it?"; then
  # The old image is still on the Host (removing a container keeps its image); cp -a keeps owners and modes.
  operator "sudo docker volume create $NEW_APPRISE_VOLUME >/dev/null && sudo docker run --rm --pull never \
    --network none -v $OLD_APPRISE_VOLUME:/from:ro -v $NEW_APPRISE_VOLUME:/to --entrypoint sh $OLD_APPRISE_IMAGE \
    -c 'cp -a /from/. /to/'"
  [[ "$(count "$OLD_APPRISE_VOLUME" "$OLD_APPRISE_IMAGE")" == "$(count "$NEW_APPRISE_VOLUME" "$OLD_APPRISE_IMAGE")" ]] \
    || die "the copy differs from $OLD_APPRISE_VOLUME"
  ok "copied; both hold the same number of entries"
else
  die "the ops Stack's apprise needs $NEW_APPRISE_VOLUME; re-run when ready"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Retire common's stack-back (common-backup)"
say "#300 moved stack-back from common to ops. Redeploy common by hand from main so common-backup is"
say "removed before the ops Stack's stack-back starts: two would both run the daily backup."
say "Both schedules are 09:12 Host time; don't run this stage around then."
note "Host time now: $(agent date +%H:%M)"
if ! exists container common-backup; then
  ok "common-backup is already gone"
else
  say "First a dry run, in $OPERATOR's ~/ops checkout after git pull:"
  operator 'cd ~/ops && git pull -q --ff-only && cd nc8kg1101/common && sudo docker compose up -d --remove-orphans --dry-run'
  note "Expect only common-backup to be removed; anything else listed is drift from main and changes too."
  confirm "Redeploy common for real (removes common-backup)?" \
    || die "the ops Stack's stack-back must not run beside common-backup; re-run when ready"
  operator 'cd ~/ops/nc8kg1101/common && sudo docker compose up -d --remove-orphans'
  ! exists container common-backup || die "common-backup is still there"
  ok "common-backup removed"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Bootstrap doco-cd"
DOCO_IMAGE=$(image doco-cd)
say "A one-shot doco-cd ($DOCO_IMAGE) clones $REPO_URL, reads .doco-cd.nc8kg1101.yml, deploys"
say "nc8kg1101/ops, decrypting its SOPS files with the Host key, and exits. What is left is the doco-cd container,"
say "labelled so it manages itself (and every Stack under nc8kg1101/) from main from now on."
legacy_snapshot > "$STATE_DIR/legacy-before"
note "Recorded $(wc -l < "$STATE_DIR/legacy-before" | tr -d ' ') legacy containers to compare afterwards."
if [[ -n "$(agent "sudo -n docker ps -q --filter name=^doco-cd\$ --filter label=cd.doco.deployment.name=ops")" ]]; then
  ok "doco-cd is already running from the ops Stack"
elif confirm "Run the bootstrap now?"; then
  # Flow-style POLL_CONFIG, so it survives ssh in one line; it matches the one in doco-cd/service.yaml.
  operator "sudo docker run --rm --name doco-cd-bootstrap \
    -v /var/run/docker.sock:/var/run/docker.sock -v ops_doco-cd_data:/data \
    -v $HOST_AGE_KEY:/run/secrets/sops_age_key:ro -e SOPS_AGE_KEY_FILE=/run/secrets/sops_age_key \
    -e SELF_UPDATE_ENABLED=true \
    -e 'POLL_CONFIG=[{url: $REPO_URL, reference: main, target: nc8kg1101, interval: 120}]' \
    $DOCO_IMAGE apply-self --bootstrap" || die "the bootstrap failed; its log is above. Fix and re-run this wizard."
  ok "bootstrap finished"
else
  die "nothing deployed; re-run when ready"
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Verify"
failed=0
wait_healthy doco-cd || failed=1
say "The ops Stack, deployed by doco-cd:"
agent "sudo -n docker ps -a --filter label=com.docker.compose.project=ops \
  --format '  {{.Names}}  {{.Status}}  deployed-by-doco-cd={{.Label \"cd.doco.deployment.name\"}}'"
[[ "$(agent "sudo -n docker ps -q --filter label=cd.doco.deployment.name=ops" | wc -l | tr -d ' ')" == 3 ]] \
  || { warn "expected 3 running ops containers labelled by doco-cd"; failed=1; }
say "Waiting for the doco-cd container's own first poll of main (up to 4 minutes)..."
poll=""
for _ in $(seq 1 48); do
  poll=$(agent "sudo -n docker logs doco-cd 2>&1 | grep -E 'job completed (successfully|with errors)' | tail -n1" || true)
  [[ -n "$poll" ]] && break
  sleep 5
done
if [[ "$poll" == *successfully* ]]; then
  ok "doco-cd polled main and finished without errors"
else
  warn "doco-cd's first poll ${poll:+failed: $poll}${poll:-did not finish}; see sudo docker logs doco-cd"
  failed=1
fi
wait_healthy stack-back || failed=1
say "stack-back's schedule:"
agent "sudo -n docker exec stack-back crontab -l" || failed=1
wait_healthy apprise || failed=1
APPRISE_IMAGE=$(image apprise)
code=$(agent "sudo -n docker run --rm --pull never --network common_backend --entrypoint curl $APPRISE_IMAGE \
  -s -o /dev/null -w '%{http_code}' http://apprise:8000/json/urls/asotdiscord" || true)
if [[ "$code" == 200 ]]; then
  ok "xfer's Services reach apprise:8000 on common_backend, and it holds the asotdiscord config"
else
  warn "GET apprise:8000/json/urls/asotdiscord from common_backend returned ${code:-nothing}"
  failed=1
fi
owners=$(agent "sudo -n docker ps -a --filter label=cd.doco.deployment.name \
  --format '{{.Label \"com.docker.compose.project\"}}'" | sort -u | tr '\n' ' ')
if [[ "$owners" == "ops " ]]; then
  ok "doco-cd manages only the ops Stack"
else
  warn "doco-cd labels containers in: $owners"
  failed=1
fi
legacy_snapshot > "$STATE_DIR/legacy-after"
if diff -u "$STATE_DIR/legacy-before" "$STATE_DIR/legacy-after"; then
  ok "no legacy container (${LEGACY_PROJECTS// /, }) was created, removed or restarted by the bootstrap"
else
  warn "legacy containers changed during the bootstrap (diff above)"
  failed=1
fi
(( failed == 0 )) || die "verification failed; see above. Rollback: README.md#bootstrapping-doco-cd"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Clean up"
RELEASE=$(date -v+7d +%F 2>/dev/null || date -d '+7 days' +%F)
say "Leftovers of the old services:"
if exists volume common_backup_cache \
  && confirm "Remove volume common_backup_cache (common-backup's restic cache; regenerable)?"; then
  operator "sudo docker volume rm common_backup_cache >/dev/null"
  ok "removed"
fi
say "Release on $RELEASE, once notifications and backups still work (until then a rollback needs both):"
step "Rollback Volume $OLD_APPRISE_VOLUME: ssh -t $OPERATOR sudo docker volume rm $OLD_APPRISE_VOLUME"
step "common's plaintext env: ssh $OPERATOR 'shred -u ~/ops/nc8kg1101/common/stack-back.env'"
SKIPPED+=("on $RELEASE: remove $OLD_APPRISE_VOLUME, shred ~/ops/nc8kg1101/common/stack-back.env, tick #300's PR")
pause

finish
